with parsed as (select id, level, status_code, payload_json, array_contains(map_keys(context), 'region') as has_region, coalesce(context['trace'], 'direct') as trace_or_default, shiftright(status_code, 2) as status_code_high, get_json_object(payload_json, '$.user.tier') as user_tier from app_logs) select level, count(distinct trace_or_default) as distinct_trace_or_defaults, max(status_code_high) filter (where level = 'WARN') as warn_max_status_code_high, count(*) as event_count, approx_percentile(status_code, 0.95) as status_code_p95, bit_and(status_code) as status_code_bit_and from parsed group by 1 order by status_code_p95 desc
